class Solution {
    private val mod=1000000007;
    private lateinit var digits:CharArray;
    private var minSum=0;
    private var maxSum=0;
    private lateinit var memo:Array<IntArray>;
    private fun dfs(pos:Int,sum:Int,tight:Boolean):Int{
        if(sum>maxSum)return 0;
        if(pos==digits.size)return if(sum>=minSum)1 else 0;
        if(!tight&&memo[pos][sum]!=-1)return memo[pos][sum];
        val limit=if(tight)digits[pos]-'0' else 9;
        var ways=0L;
        for(digit in 0..limit)ways=(ways+dfs(pos+1,sum+digit,tight&&digit==limit))%mod;
        val answer=ways.toInt();
        if(!tight)memo[pos][sum]=answer;
        return answer
    };
    private fun countUpTo(bound:String):Int{
        digits=bound.toCharArray();
        memo=Array(digits.size){
            IntArray(maxSum+1){
                -1
            }
        };
        return dfs(0,0,true)
    };
    private fun valid(value:String):Boolean{
        var sum=0;
        for(ch in value)sum+=ch-'0';
        return sum in minSum..maxSum
    };
    fun count(num1:String,num2:String,min_sum:Int,max_sum:Int):Int{
        minSum=min_sum;
        maxSum=max_sum;
        var answer=(countUpTo(num2).toLong()-countUpTo(num1)+if(valid(num1))1 else 0)%mod;
        if(answer<0)answer+=mod;
        return answer.toInt()
    }
}

